create or replace TABLE LDL_DATA_PRODUCTION.META.T_DIM_DATA_QUALITY_RULE_2 (
	TEST_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a data quality rule.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	DQ_RULE_NAME VARCHAR(250) NOT NULL COMMENT 'The name by which the data quality rule has been defined.',
	DQ_RULE_DESCR VARCHAR(250) COMMENT 'A free text describing the character and purpose of the data quality rule.',
	DQ_RULE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'A code for the subtype discriminators for data quality rules. It distinguishes between business rules, generated and parametrized rules.',
	DQ_RULE_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminators for data quality rules. It distinguishes between business rules, generated and parametrized rules.',
	DQ_RULE_TEMPLATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the template which was used to generate a formal data quality rule.',
	DQ_RULE_TEMPLATE_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the template script which was used to generate a formal data quality rule.',
	TESTED_SYS_NAME VARCHAR(100) NOT NULL COMMENT 'This test_2 targets a table. This attribute contains the name of the IT system in which this table resides.',
	TESTED_DB_NAME VARCHAR(100) NOT NULL COMMENT 'This test_2 targets a table. This attribute contains the name of the database in which this table resides.',
	TESTED_SCHEMA_NAME VARCHAR(100) NOT NULL COMMENT 'This test_2 targets a table. This attribute contains the name of the schema in which this table resides.',
	TESTED_TABLE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the table which is the target of this test. In case the data quality check works on a view, then this is the underlying table. If the view uses multiple tables, this is the primary table.',
	TESTED_TABLE_NAME VARCHAR(250) NOT NULL COMMENT 'The name of the table, which is the target of this test. In case the data quality check works on a view, then this is the underlying table. If the view uses multiple tables, this is the primary table.',
	TEST_ORIGIN_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the operational source which defines the test.',
	TEST_ORIGIN_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the operational source which defines the test.',
	TEST_LIFECYCLE_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the lifecycle status_2 of a test. E.g. draft, approved, expired, ...',
	TEST_LIFECYCLE_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the lifecycle status_2 of a test.',
	SCHEDULING_FREQ_CD VARCHAR(20) NOT NULL COMMENT 'A code defining, how often the data quality rule is executed. E.g daily, weekly, ...',
	SCHEDULING_FREQ_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the scheduling frequency.',
	DQ_DIMENSION_CD VARCHAR(20) NOT NULL COMMENT 'A code identifying the basic aspect by which data quality is measured. E.g. correctness, timeliness, completeness, consistency, etc.',
	DQ_DIMENSION_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the basic aspect by which data quality is measured. E.g. correctness, timeliness, completeness, consistency, etc.',
	DQ_RULE_SRC_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the origin of the data quality rule. A rule may be defined by business or by the data modelling team or because of a formal guideline, such as checking all foreign keys for referential integrity violations. (Note that the origin of a data quality rule is independent from the way how it is implemented, i.e. as a generated rule, a parametrized rule or as a business rule.)',
	DQ_RULE_SRC_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the origin of the data quality rule.',
	DQ_RULE_CRITICALITY_LVL_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the criticality level for a data quality rule. E.g. high, medium, low.',
	DQ_RULE_CRITICALITY_LVL_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the criticality level for a data quality rule. E.g. high, medium, low.',
	DQ_PROJECT_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the data quality project.',
	DQ_PROJECT_NAME VARCHAR(100) NOT NULL COMMENT 'The name by which the data quality project is known.',
	RULE_PRIO NUMBER(38,0) COMMENT 'Optionally, a weight can be assigned to a data quality rule. In an aggregation the results of the rule are weighted accordingly.',
	SQL_TXT VARCHAR(32000) COMMENT 'The SQL statement which runs the data quality check.',
	RWI_SQL_TXT VARCHAR(32000) COMMENT 'The SQL statement which selects those records from the tested data structure which violate the data quality rule.',
	RWI_COND_SQL_TXT VARCHAR(32000) COMMENT 'The SQL statement which selects those records from the tested data structure which violate the data quality rule. The statement contains an additional condition which limits the number of records to those ones that are of highest interest, e.g. to the most recent ones.',
	COMMENT_TXT VARCHAR(1000) COMMENT 'A free text comment to the data quality rule.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_DATA_QUALITY_RULE primary key (TEST_SID, DWH_VALID_FROM_TMSP)
)COMMENT='A data quality rule checks, if records conform to a certain condition. E.g. prices must be positive, or referential integrity. A data quality rule returns the number of records that have passed the check, and the number of records which have failed the check.'
;